pub(super) fn exact_file_path(path: &Path, label: &str) -> Result<PathBuf> {
    let path = fs::canonicalize(path)
        .with_context(|| format!("foreign-process {label} path is unavailable"))?;
    if !path.is_absolute() {
        bail!("foreign-process {label} path must resolve absolutely");
    }
    Ok(path)
}

pub(super) fn script_extension(path: &Path) -> Result<String> {
    let extension = path
        .extension()
        .and_then(|value| value.to_str())
        .context("foreign-process script requires a UTF-8 extension")?;
    Ok(format!(".{extension}"))
}

pub(super) fn parse_environment(values: &[String]) -> Result<BTreeMap<String, String>> {
    let mut environment = BTreeMap::new();
    for entry in values {
        let (key, value) = entry
            .split_once('=')
            .context("foreign-process environment entries require KEY=VALUE")?;
        if environment
            .insert(key.to_owned(), value.to_owned())
            .is_some()
        {
            bail!("foreign-process environment keys must be unique");
        }
    }
    value::validate_environment(&environment)?;
    Ok(environment)
}

